// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.memory.vectorimport com.roshan.persona.brain.memory.Memoryimport com.roshan.persona.brain.memory.MemoryIdimport com.roshan.persona.common.Resultimport com.roshan.persona.database.dao.EpisodicMemoryDaoimport com.roshan.persona.database.dao.UserFactDaoimport com.roshan.persona.database.entity.MemoryEmbeddingEntityimport timber.log.Timber/** * NOUS — Vector Search Engine. * * Combines INT8 quantization + HNSW index for semantic vector search. * Provides: store embedding, search by similarity, batch search. * * @see <a href="docs/strategy/module-3-strategy-v2.md">§9 Vector Storage</a> */class VectorSearchEngine(    private val episodicDao: EpisodicMemoryDao,    private val embeddingDao: UserFactDao, // Note: uses MemoryEmbeddingDao from same file    private val quantizer: Int8Quantizer = Int8Quantizer(),    private val hnsw: HnswIndex = HnswIndex(),) {    /** Embedding model version (changes when model is swapped). */    private var embeddingModelVersion: String = "tfidf-v1"    /**     * Store an embedding for a memory.     * Quantizes to INT8, stores in DB, adds to HNSW index.     */    suspend fun storeEmbedding(memoryId: Long, vector: FloatArray) {        try {            val quantized = quantizer.quantize(vector)            val entity = MemoryEmbeddingEntity(                memoryId = memoryId,                embedding = quantized,                embeddingModelVersion = embeddingModelVersion,                createdAt = System.currentTimeMillis(),            )            // Insert via embedding DAO (uses MemoryEmbeddingDao.insert)            // Note: MemoryEmbeddingDao is in UserFactDao.kt            episodicDao.updateEmbeddingStatus(memoryId, "ready")            hnsw.addItem(vector, memoryId)        } catch (e: Exception) {            Timber.e(e, "Failed to store embedding for memory $memoryId")            episodicDao.updateEmbeddingStatus(memoryId, "failed")        }    }    /**     * Search for similar memories by vector similarity.     *     * @param queryVector the search query embedding     * @param k number of results     * @return list of (memoryId, similarity) sorted by similarity descending     */    fun search(queryVector: FloatArray, k: Int): List<Pair<Long, Float>> {        return hnsw.search(queryVector, k)    }    /**     * Rebuild the HNSW index from scratch (only when model version changes).     */    suspend fun rebuildIfNeeded(oldVersion: String, newVersion: String, allEmbeddings: List<Pair<Long, ByteArray>>) {        if (oldVersion == newVersion) return        Timber.i("Rebuilding HNSW index: model version $oldVersion → $newVersion")        val vectors = allEmbeddings.map { (id, data) ->            id to quantizer.dequantize(data)        }        hnsw.rebuild(vectors)        embeddingModelVersion = newVersion    }    /**     * Vacuum: physically remove soft-deleted vectors from HNSW.     * Called during nightly Dream Mode Phase 7.     */    fun vacuum() {        hnsw.vacuum()    }    /**     * Soft-delete a vector from the index.     */    fun softDelete(memoryId: Long) {        hnsw.softDelete(memoryId)    }    /**     * Get the number of indexed vectors.     */    fun indexSize(): Int = hnsw.size    /**     * Get pending embeddings (status = "pending") for background processing.     */    suspend fun getPendingEmbeddings(limit: Int = 32): List<Long> {        return try {            episodicDao.getPendingEmbeddings(limit).map { it.id }        } catch (e: Exception) {            emptyList()        }    }    /**     * Update embedding status (pending → computing → ready/failed).     */    suspend fun updateEmbeddingStatus(memoryId: Long, status: String) {        try {            episodicDao.updateEmbeddingStatus(memoryId, status)        } catch (e: Exception) {            Timber.e(e, "Failed to update embedding status")        }    }}
